"use client";

import { useEffect, useId, useMemo, useRef, useState, useSyncExternalStore, type ComponentProps, type KeyboardEvent, type ReactNode } from "react";

import { IconAlertCircle, IconBarcode, IconCalendar, IconPackage, IconReceipt, IconShieldCheck } from "@rhs-ui/icons";
import { WarrantyConfirmation } from "@rhs-ui/commerce/warranty-registration/confirmation";
import {
  FIELD_ORDER,
  checkField,
  compilePattern,
  dateOfIso,
  dayText,
  durationText,
  addMonths,
  isoOfDate,
  knownZone,
  tidySerial,
  todayIn,
  validate,
  type FieldErrors,
  type FieldKey,
  type WarrantyAnswers,
  type WarrantyMoment,
  type WarrantyProduct,
  type WarrantyReceipt,
  type WarrantyRules,
  type WarrantyValues,
} from "@rhs-ui/commerce/warranty-registration/warranty";
import { fill, wordsOf, type WarrantyRegistrationLabels, type WarrantyWords } from "@rhs-ui/commerce/warranty-registration/words";
import { Alert, AlertDescription, AlertTitle } from "@rhs-ui/primitives/alert";
import { Badge } from "@rhs-ui/primitives/badge";
import { Button } from "@rhs-ui/primitives/button";
import { Checkbox } from "@rhs-ui/primitives/checkbox";
import { DatePicker } from "@rhs-ui/primitives/date-picker";
import { FileTrigger } from "@rhs-ui/primitives/file-trigger";
import { FormControl, FormDescription, FormField, FormLabel } from "@rhs-ui/primitives/form-field";
import { Input } from "@rhs-ui/primitives/input";
import { cn } from "@/lib/utils";

export type { WarrantyMoment, WarrantyProduct, WarrantyReceipt, WarrantyValues } from "@rhs-ui/commerce/warranty-registration/warranty";
export type { WarrantyRegistrationLabels } from "@rhs-ui/commerce/warranty-registration/words";

export interface WarrantyRegistrationProps extends Omit<ComponentProps<"section">, "children" | "title" | "onSubmit"> {
  /** The product that is being registered, when you know it. It is shown beside the form and the form does not ask for it. Without it the form has a field for the product. */
  product?: WarrantyProduct;
  /** Called with the answers once every check has passed. Return a message to say the shop could not take it (the form stays, with every answer in it, the receipt too); return nothing, or resolve, and the form is replaced by the confirmation. Return `{ reference }` to print the registration's reference on the confirmation. */
  onSubmit?: (values: WarrantyValues) => string | WarrantyReceipt | void | Promise<string | WarrantyReceipt | void>;
  /** How many months the warranty runs from the day of purchase. It is worked out and shown before the form is sent. Defaults to 24. */
  warrantyMonths?: number;
  /** What a serial number looks like. A string is a regular expression's source (`"^HX-\\d{4}-[A-Z0-9]{4}$"`, matched without regard to case) and can cross from a Server Component; a RegExp keeps its own flags. A serial number that does not fit is explained in words. Without it any serial number is accepted. */
  serialPattern?: RegExp | string;
  /** Where the serial number is printed, under the field: "On the label under the base, after S/N." */
  serialHelp?: ReactNode;
  /** An example that fits the pattern. It is the field's placeholder, written as an example ("For example HX-4821-K9Q2") so an empty field never looks filled in, and it is quoted in the message when a serial number does not fit. */
  serialExample?: string;
  /** The largest receipt in bytes. A bigger file is refused with the reason in words. Defaults to 5 MB. */
  maxFileSize?: number;
  /** Whether a receipt must be attached. Defaults to true; with false the field says it is optional. */
  proofRequired?: boolean;
  /** What the warranty covers, one line each, for the confirmation. Left out when empty. */
  covers?: readonly string[];
  /** What it does not cover, one line each, for the confirmation. */
  excludes?: readonly string[];
  /** Where the privacy notice is. The consent line then ends in a link that opens in a new tab. */
  privacyHref?: string;
  /** Where "Back to the shop" goes on the confirmation. Without it there is no link. */
  shopHref?: string;
  /** Answers to start with, such as the shop and the day when the customer comes from an order. The day is yyyy-mm-dd. */
  defaultValues?: Partial<Omit<WarrantyValues, "proof" | "coveredUntil">>;
  /** Show the confirmation for these answers instead of the form, for a page that has already registered the product. */
  submitted?: WarrantyValues & WarrantyReceipt;
  /** The moment "today" is measured from, for the check that the day is not in the future and the cover has not ended. Pass it from the server so the first render matches the browser's; without it the browser's clock is used once the page has loaded. */
  now?: WarrantyMoment;
  /** The shop's time zone: it decides which calendar day "today" is. Defaults to "UTC". */
  timeZone?: string;
  /** Always pass your application locale, so the server and the browser write the same dates. */
  locale?: string;
  /** The heading. Defaults to "Register your {product}". */
  title?: string;
  /** The line under it. */
  description?: string;
  /** The heading's element: "h2" by default, "h3" inside a section that has its own h2. */
  headingAs?: "h2" | "h3";
  /** The words, for another language. */
  labels?: WarrantyRegistrationLabels;
}

interface State {
  product: string;
  serial: string;
  purchaseDate: Date | null;
  store: string;
  proof: File | null;
  consent: boolean;
}

const noSubscription = (): (() => void) => () => undefined;

/** The shop's calendar day: from `now` when you pass it, otherwise the browser's clock once the page has loaded (never on the server, so nothing mismatches). */
function useToday(now: WarrantyMoment | undefined, zone: string): string | null {
  const given = now === undefined ? null : todayIn(now, zone);
  const clock = useSyncExternalStore(
    noSubscription,
    () => todayIn(Date.now(), zone),
    () => null,
  );
  return given ?? clock;
}

interface FieldProps {
  name: FieldKey;
  label: string;
  hint?: ReactNode;
  optional?: string;
  error?: string;
  className?: string;
  children: ReactNode;
  base: string;
}

/** One label, one control, a hint and an error, wired together. The wrapper carries the name the form focuses by. */
function Field({ name, label, hint, optional, error, className, children, base }: FieldProps) {
  return (
    <FormField id={`${base}-${name}`} data-field={name} error={error} described={Boolean(hint)} className={className}>
      <FormLabel>
        {label}
        {optional ? <span className="font-normal text-muted-foreground">({optional})</span> : null}
      </FormLabel>
      {children}
      {hint ? <FormDescription>{hint}</FormDescription> : null}
    </FormField>
  );
}

interface AsideProps {
  product?: WarrantyProduct;
  duration: string;
  words: WarrantyWords;
  id: string;
}

/** The product the form is for, and what to have ready. A narrow form gets the product as one row and no list. It comes first in the markup so it sits first on a wide form, which is why "Have ready" is the name of a group and not a heading: the form's own heading is the first one a screen reader meets. */
function Aside({ product, duration, words, id }: AsideProps) {
  const ready = [IconBarcode, IconCalendar, IconReceipt] as const;
  return (
    <div className="grid content-start gap-7">
      {product ? (
        <div
          data-slot="warranty-registration-product"
          className="grid grid-cols-[4rem_minmax(0,1fr)] items-center gap-4 rounded-xl border border-border bg-card p-3 shadow-xs @3xl:grid-cols-1 @3xl:gap-0 @3xl:overflow-hidden @3xl:p-0"
        >
          <span aria-hidden="true" className="grid aspect-square place-items-center overflow-hidden rounded-lg bg-muted @3xl:aspect-[4/3] @3xl:rounded-none">
            {product.image ? (
              // eslint-disable-next-line @next/next/no-img-element -- framework-neutral; the picture is decorative, the name is beside it
              <img src={product.image} alt="" loading="lazy" decoding="async" className="size-full object-cover" />
            ) : (
              <IconPackage className="size-6 text-muted-foreground @3xl:size-9" />
            )}
          </span>
          <div className="min-w-0 @3xl:p-4">
            <p className="text-sm leading-snug font-medium [overflow-wrap:anywhere]">{product.name}</p>
            {product.model ? <p className="mt-0.5 text-xs text-muted-foreground tabular-nums [overflow-wrap:anywhere]">{fill(words.modelLine, { model: product.model })}</p> : null}
            <Badge variant="muted" className="mt-2 @3xl:mt-3">
              <IconShieldCheck aria-hidden="true" />
              {fill(words.warrantyBadge, { duration })}
            </Badge>
          </div>
        </div>
      ) : null}

      <div role="group" aria-labelledby={`${id}-ready`} className="hidden gap-3 @3xl:grid">
        <p id={`${id}-ready`} className="text-sm font-medium">
          {words.readyTitle}
        </p>
        <ul role="list" className="grid gap-3">
          {words.ready.map((line, index) => {
            const Icon = ready[index] ?? IconReceipt;
            return (
              <li key={line} className="flex items-center gap-3 text-sm leading-snug">
                <span aria-hidden="true" className="grid size-8 shrink-0 place-items-center rounded-lg border border-border bg-card text-muted-foreground">
                  <Icon className="size-4" />
                </span>
                <span className="min-w-0">{line}</span>
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

/**
 * Registering a purchase for its warranty: the product (shown when you know it), the serial number with a hint of
 * where to find it and a check against the pattern you give, the day it was bought, the shop or order number, the
 * receipt and a consent line. As soon as a day is chosen the form says when the cover ends ("Covered until 14 March
 * 2028"), so the customer sees what registering gets them before sending. A serial number that does not fit is
 * explained in words, a send that fails keeps every answer and the receipt's name, and a send that works replaces the
 * form with the confirmation: the end date, what was registered, what is covered and a reference. It gives durable
 * goods a reason to be registered and the customer proof that they are.
 */
export function WarrantyRegistration({
  product,
  onSubmit,
  warrantyMonths = 24,
  serialPattern,
  serialHelp,
  serialExample,
  maxFileSize = 5_000_000,
  proofRequired = true,
  covers,
  excludes,
  privacyHref,
  shopHref,
  defaultValues,
  submitted,
  now,
  timeZone = "UTC",
  locale = "en-US",
  title,
  description,
  headingAs: Heading = "h2",
  labels,
  className,
  ...props
}: WarrantyRegistrationProps) {
  const words = wordsOf(labels);
  const base = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const root = useRef<HTMLElement>(null);
  const banner = useRef<HTMLDivElement>(null);
  const proofGroup = useRef<HTMLDivElement>(null);
  const zone = knownZone(timeZone);
  const pattern = useMemo(() => compilePattern(serialPattern), [serialPattern]);
  const today = useToday(now, zone);
  const [state, setState] = useState<State>(() => ({
    product: defaultValues?.product ?? "",
    serial: defaultValues?.serial ?? "",
    purchaseDate: defaultValues?.purchaseDate ? dateOfIso(defaultValues.purchaseDate) : null,
    store: defaultValues?.store ?? "",
    proof: null,
    consent: defaultValues?.consent ?? false,
  }));
  const [errors, setErrors] = useState<FieldErrors>({});
  const [pending, setPending] = useState(false);
  const [failure, setFailure] = useState<string | null>(null);
  const [sent, setSent] = useState<(WarrantyValues & WarrantyReceipt) | null>(null);
  const [focusTarget, setFocusTarget] = useState<FieldKey | "banner" | "sent" | null>(null);

  const duration = durationText(warrantyMonths, locale);
  const done = submitted ?? sent;

  const rulesAt = (day: string | null): WarrantyRules => ({
    asksProduct: !product,
    pattern,
    example: serialExample ?? "",
    months: warrantyMonths,
    proofRequired,
    today: day,
    locale,
    errors: words.errors,
  });
  const answersOf = (from: State): WarrantyAnswers => ({
    product: product?.name ?? from.product,
    serial: from.serial,
    purchaseDate: from.purchaseDate ? isoOfDate(from.purchaseDate) : null,
    store: from.store,
    proof: from.proof,
    consent: from.consent,
  });

  const purchaseIso = state.purchaseDate ? isoOfDate(state.purchaseDate) : null;
  const endIso = purchaseIso ? addMonths(purchaseIso, warrantyMonths) : null;
  // The preview shows only for a day that can be registered: not in the future and with the cover still running.
  const dayProblem = checkField("purchaseDate", answersOf(state), rulesAt(today));
  const preview = endIso && !dayProblem ? endIso : null;
  const latest = today ? dateOfIso(today) : null;

  // Focus goes where the news is: the first field that needs a look, the notice that the send failed, or the confirmation.
  useEffect(() => {
    if (focusTarget === null) return;
    const node =
      focusTarget === "banner"
        ? banner.current
        : focusTarget === "sent"
          ? root.current?.querySelector<HTMLElement>("[data-focus-target]")
          : root.current?.querySelector<HTMLElement>(`[data-field="${focusTarget}"] :is(input:not([type="hidden"]), button, textarea)`);
    node?.focus();
    setFocusTarget(null);
  }, [focusTarget]);

  // Once a file is chosen the file field swaps its button for the file's row and leaves the real input behind, hidden and still in the tab order, with no label. While a file is attached that input is taken out of both; the row's own remove button is the control.
  useEffect(() => {
    const input = proofGroup.current?.querySelector<HTMLInputElement>('input[type="file"]');
    if (!input) return;
    if (state.proof) {
      input.setAttribute("aria-hidden", "true");
      input.tabIndex = -1;
    } else {
      input.removeAttribute("aria-hidden");
      input.removeAttribute("tabindex");
    }
  }, [state.proof]);

  // A day that came with the form, from the order, is checked as soon as today is known.
  useEffect(() => {
    if (today && state.purchaseDate) recheck("purchaseDate", state);
    // Only when the clock becomes known: later changes go through set().
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [today]);

  function recheck(key: FieldKey, next: State) {
    const message = checkField(key, answersOf(next), rulesAt(today));
    setErrors((current) => {
      const copy = { ...current };
      if (message) copy[key] = message;
      else delete copy[key];
      return copy;
    });
  }

  function set<K extends keyof State>(key: K, value: State[K]) {
    const next = { ...state, [key]: value };
    setState(next);
    // A field that already shows a problem is checked again as it changes, so the problem goes the moment it is fixed.
    // A day is chosen on purpose rather than typed, so it is checked at once: a day that is too old says so before anything is sent.
    if (key in errors || (key === "purchaseDate" && value !== null)) recheck(key as FieldKey, next);
  }

  async function submit() {
    if (pending) return;
    setFailure(null);
    const answers = answersOf(state);
    const found = validate(answers, rulesAt(todayIn(now ?? Date.now(), zone)));
    setErrors(found);
    const first = FIELD_ORDER.find((key) => found[key]);
    if (first) {
      setFocusTarget(first);
      return;
    }
    const day = answers.purchaseDate ?? "";
    const values: WarrantyValues = {
      product: answers.product.trim(),
      serial: tidySerial(answers.serial),
      purchaseDate: day,
      store: answers.store.trim(),
      proof: answers.proof,
      consent: answers.consent,
      coveredUntil: addMonths(day, warrantyMonths) ?? day,
    };
    setPending(true);
    try {
      const result = await onSubmit?.(values);
      if (typeof result === "string" && result.length > 0) {
        setFailure(result);
        setFocusTarget("banner");
      } else {
        setSent({ ...values, reference: result && typeof result === "object" ? result.reference : undefined });
        setFocusTarget("sent");
      }
    } catch {
      setFailure(words.failedMessage);
      setFocusTarget("banner");
    } finally {
      setPending(false);
    }
  }

  /** Enter in a text field sends the form, as it would in a form element. Keys from the open calendar are not inside this element, so they never get here. */
  function sendOnEnter(event: KeyboardEvent<HTMLDivElement>) {
    const target = event.target;
    if (event.key !== "Enter" || event.defaultPrevented || !(target instanceof HTMLInputElement) || !event.currentTarget.contains(target)) return;
    if (["checkbox", "radio", "file", "button", "submit"].includes(target.type)) return;
    event.preventDefault();
    void submit();
  }

  const titleId = `${base}-title`;
  const heading = title ?? (product ? fill(words.titleNamed, { product: product.name }) : words.title);

  if (done) {
    return (
      <section ref={root} data-slot="warranty-registration" aria-labelledby={titleId} className={cn("@container min-w-0", className)} {...props}>
        <WarrantyConfirmation
          titleId={titleId}
          headingAs={Heading}
          values={done}
          model={product?.model}
          months={warrantyMonths}
          covers={covers}
          excludes={excludes}
          reference={done.reference}
          shopHref={shopHref}
          words={words}
          locale={locale}
        />
        <p role="status" className="sr-only">
          {fill(words.sentStatus, { date: dayText(done.coveredUntil, locale) })}
        </p>
      </section>
    );
  }

  const size = new Intl.NumberFormat(locale, { style: "unit", unit: "megabyte", maximumFractionDigits: 1 }).format(maxFileSize / 1e6);

  return (
    <section ref={root} data-slot="warranty-registration" aria-labelledby={titleId} className={cn("@container min-w-0", className)} {...props}>
      {/* Not a <form> element: Radix draws a hidden native input beside every checkbox inside one and clicks it from an effect, which React reports in development. Enter in a text field still sends it. */}
      <div onKeyDown={sendOnEnter} className="grid gap-8 @3xl:grid-cols-[16rem_minmax(0,1fr)] @3xl:gap-14">
        <Aside product={product} duration={duration} words={words} id={base} />

        <div className="grid min-w-0 content-start gap-7">
          <header className="grid gap-2">
            <Heading id={titleId} className="text-2xl leading-tight font-medium tracking-[-0.035em] text-balance @3xl:text-3xl">
              {heading}
            </Heading>
            <p className="max-w-prose text-base leading-relaxed text-pretty text-muted-foreground">{description ?? words.description}</p>
            {!proofRequired ? <p className="text-xs text-muted-foreground">{words.requiredNote}</p> : null}
          </header>

          {failure ? (
            <Alert ref={banner} tabIndex={-1} tone="destructive" role="group" aria-labelledby={`${base}-failed`} className="outline-none focus-visible:ring-[3px] focus-visible:ring-destructive/30">
              <IconAlertCircle aria-hidden="true" />
              <AlertTitle id={`${base}-failed`} className="text-foreground">
                {words.failedTitle}
              </AlertTitle>
              <AlertDescription className="text-foreground">
                <p>{failure}</p>
                <p className="text-muted-foreground">{words.failedHint}</p>
              </AlertDescription>
            </Alert>
          ) : null}

          <div className="grid items-start gap-x-5 gap-y-6 @xl:grid-cols-2">
            {!product ? (
              <Field base={base} name="product" label={words.fields.product} hint={words.hints.product} error={errors.product} className="@xl:col-span-2">
                <FormControl>
                  <Input name="product" autoComplete="off" placeholder={words.productPlaceholder} value={state.product} onChange={(event) => set("product", event.target.value)} />
                </FormControl>
              </Field>
            ) : null}

            <Field base={base} name="serial" label={words.fields.serial} hint={serialHelp} error={errors.serial} className="@xl:col-span-2">
              <FormControl>
                <Input
                  name="serial"
                  autoComplete="off"
                  autoCapitalize="characters"
                  spellCheck={false}
                  placeholder={serialExample ? fill(words.serialPlaceholderExample, { example: serialExample }) : words.serialPlaceholder}
                  value={state.serial}
                  onChange={(event) => set("serial", event.target.value)}
                  onBlur={() => {
                    if (state.serial.trim()) recheck("serial", state);
                  }}
                  className="font-mono tracking-tight uppercase placeholder:normal-case"
                />
              </FormControl>
            </Field>

            <Field base={base} name="purchaseDate" label={words.fields.purchaseDate} error={errors.purchaseDate}>
              <FormControl>
                <DatePicker
                  name="purchase-date"
                  value={state.purchaseDate}
                  onValueChange={(day) => set("purchaseDate", day)}
                  max={latest ?? undefined}
                  locale={locale}
                  placeholder={words.datePlaceholder}
                  className={cn("w-full", errors.purchaseDate && "border-destructive ring-destructive/25")}
                />
              </FormControl>
            </Field>

            <Field base={base} name="store" label={words.fields.store} hint={words.hints.store} error={errors.store}>
              <FormControl>
                <Input name="store" autoComplete="off" value={state.store} onChange={(event) => set("store", event.target.value)} />
              </FormControl>
            </Field>

            {/* A status region that is always there, so the end of the cover is read out when a day is chosen. */}
            <div role="status" className="@xl:col-span-2 empty:hidden">
              {preview ? (
                <div data-slot="warranty-registration-cover" className="flex items-center gap-3.5 rounded-xl border border-border bg-muted/50 px-4 py-3.5">
                  <span aria-hidden="true" className="grid size-9 shrink-0 place-items-center rounded-full bg-foreground text-background">
                    <IconShieldCheck className="size-[1.125rem]" />
                  </span>
                  <div className="min-w-0">
                    <p className="text-sm font-medium tabular-nums">{fill(words.coveredUntil, { date: dayText(preview, locale) })}</p>
                    <p className="text-xs text-muted-foreground">{fill(words.coveredFor, { duration })}</p>
                  </div>
                </div>
              ) : null}
            </div>

            <div ref={proofGroup} data-field="proof" role="group" aria-labelledby={`${base}-proof-label`} className="grid content-start gap-2 @xl:col-span-2">
              <p id={`${base}-proof-label`} className={cn("flex items-center gap-2 text-sm leading-none font-medium", errors.proof && "text-destructive")}>
                {words.fields.proof}
                {!proofRequired ? <span className="font-normal text-muted-foreground">({words.optional})</span> : null}
              </p>
              <FileTrigger onFileChange={(file) => set("proof", file)} accept=".pdf,.png,.jpg,.jpeg,image/*" maxSize={maxFileSize} label={words.proofButton} locale={locale} />
              <p className="text-xs text-muted-foreground">{fill(words.hints.proof, { size })}</p>
              <p role="status" className="text-xs font-medium text-destructive empty:hidden">
                {errors.proof}
              </p>
            </div>

            <FormField id={`${base}-consent`} data-field="consent" error={errors.consent} className="@xl:col-span-2">
              <div className="flex items-start gap-3">
                <FormControl>
                  <Checkbox checked={state.consent} onCheckedChange={(checked) => set("consent", checked === true)} className="mt-0.5" />
                </FormControl>
                <FormLabel className="block text-sm leading-snug font-normal text-foreground">
                  {words.consent}
                  {privacyHref ? (
                    <>
                      {" "}
                      <a href={privacyHref} target="_blank" rel="noreferrer" className="rounded-sm font-medium underline underline-offset-4 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/40">
                        {words.privacyLink}
                      </a>
                    </>
                  ) : null}
                </FormLabel>
              </div>
            </FormField>
          </div>

          <div className="border-t border-border pt-6">
            <Button type="button" size="lg" loading={pending} onClick={() => void submit()} className="w-full @md:w-auto">
              {pending ? words.submitting : words.submit}
            </Button>
          </div>
        </div>
      </div>
    </section>
  );
}

import { IconArrowRight, IconCheck, IconClose, IconShieldCheck } from "@rhs-ui/icons";
import { dayText, durationText, type WarrantyValues } from "@rhs-ui/commerce/warranty-registration/warranty";
import { fill, type WarrantyWords } from "@rhs-ui/commerce/warranty-registration/words";
import { Button } from "@rhs-ui/primitives/button";
import { DescriptionList, type DescriptionItem } from "@rhs-ui/primitives/description-list";
import { cn } from "@/lib/utils";

export interface WarrantyConfirmationProps {
  /** The id of the heading, so the section can be named by it. */
  titleId: string;
  /** The heading's element. */
  headingAs: "h2" | "h3";
  /** What was registered, with the last day of the cover. */
  values: WarrantyValues;
  /** The model line of the product, when it is known. */
  model?: string;
  /** How long the cover runs, in months. */
  months: number;
  /** What the warranty covers, one line each. The list is left out when empty. */
  covers?: readonly string[];
  /** What it does not cover, one line each. */
  excludes?: readonly string[];
  /** The registration's reference, when the shop gave one. */
  reference?: string;
  /** Where "Back to the shop" goes. Without it there is no link. */
  shopHref?: string;
  /** Every word the confirmation says. */
  words: WarrantyWords;
  /** The locale the dates are written in. */
  locale: string;
}

/**
 * What replaces the form once the product is registered: the end of the cover as the one big fact, what the
 * customer gave, what is covered and what is not, the reference and a way back to the shop. It keeps no state, so
 * it renders on the server too.
 */
export function WarrantyConfirmation({ titleId, headingAs: Heading, values, model, months, covers = [], excludes = [], reference, shopHref, words, locale }: WarrantyConfirmationProps) {
  const Sub = Heading === "h2" ? "h3" : "h4";
  const until = dayText(values.coveredUntil, locale);
  const bought = dayText(values.purchaseDate, locale);
  const duration = durationText(months, locale);

  const details: DescriptionItem[] = [
    { term: words.fields.product, value: <span className="[overflow-wrap:anywhere]">{values.product}</span> },
    ...(model ? [{ term: words.fields.model, value: <span className="tabular-nums [overflow-wrap:anywhere]">{model}</span> }] : []),
    { term: words.fields.serial, value: <span className="font-mono text-[0.8125rem] tracking-tight [overflow-wrap:anywhere]">{values.serial}</span> },
    { term: words.purchased, value: <span className="tabular-nums">{bought}</span> },
    { term: words.boughtAt, value: <span className="[overflow-wrap:anywhere]">{values.store}</span> },
    ...(values.proof ? [{ term: words.fields.proof, value: <span className="[overflow-wrap:anywhere]">{values.proof.name}</span> }] : []),
    ...(reference ? [{ term: words.reference, value: <span className="font-mono text-[0.8125rem] tracking-tight">{reference}</span> }] : []),
  ];

  const lists = [
    { title: words.coversTitle, lines: covers, icon: <IconCheck />, tile: "bg-foreground text-background" },
    { title: words.excludesTitle, lines: excludes, icon: <IconClose />, tile: "border border-border bg-muted text-foreground" },
  ].filter((list) => list.lines.length > 0);

  return (
    <div data-slot="warranty-registration-sent" className="grid gap-8">
      <header className="flex items-start gap-4">
        <span aria-hidden="true" className="grid size-11 shrink-0 place-items-center rounded-full bg-foreground text-background">
          <IconCheck className="size-5" strokeWidth={2.25} />
        </span>
        <div className="min-w-0">
          <Heading id={titleId} tabIndex={-1} data-focus-target="" className="text-2xl leading-tight font-medium tracking-[-0.035em] text-balance outline-none @3xl:text-3xl">
            {values.product ? fill(words.sentTitleNamed, { product: values.product }) : words.sentTitle}
          </Heading>
        </div>
      </header>

      <div className="grid gap-4 rounded-xl border border-foreground/80 bg-card p-6 shadow-xs @xl:grid-cols-[minmax(0,1fr)_auto] @xl:items-center @xl:p-7">
        <div className="min-w-0">
          <p className="text-xs font-medium tracking-[0.14em] text-muted-foreground uppercase">{words.sentCovered}</p>
          <p className="mt-2 text-3xl leading-none font-medium tracking-[-0.045em] tabular-nums @xl:text-4xl">{until}</p>
          <p className="mt-3 text-sm text-muted-foreground">{fill(words.sentFrom, { duration, date: bought })}</p>
        </div>
        <span aria-hidden="true" className="hidden size-14 shrink-0 place-items-center rounded-full border border-border bg-muted @xl:grid">
          <IconShieldCheck className="size-6" />
        </span>
      </div>

      <div role="group" aria-labelledby={`${titleId}-details`} className="grid gap-3">
        <Sub id={`${titleId}-details`} className="text-sm font-medium">
          {words.sentDetails}
        </Sub>
        <div className="rounded-xl border border-border bg-card px-5 py-5 shadow-xs">
          <DescriptionList layout="stacked" items={details} className="gap-x-8 gap-y-5 @md:grid-cols-2 @2xl:grid-cols-3" />
        </div>
      </div>

      {lists.length > 0 ? (
        <div className={cn("grid gap-8", lists.length > 1 && "@xl:grid-cols-2")}>
          {lists.map((list, index) => (
            <div role="group" key={list.title} aria-labelledby={`${titleId}-list-${index}`} className="grid content-start gap-3">
              <Sub id={`${titleId}-list-${index}`} className="text-sm font-medium">
                {list.title}
              </Sub>
              <ul role="list" className="grid gap-2.5">
                {list.lines.map((line) => (
                  <li key={line} className="flex items-start gap-3 text-sm leading-snug">
                    <span aria-hidden="true" className={cn("mt-px grid size-5 shrink-0 place-items-center rounded-full [&_svg]:size-3", list.tile)}>
                      {list.icon}
                    </span>
                    <span className="min-w-0 pt-px">{line}</span>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      ) : null}

      {shopHref ? (
        <div>
          <Button asChild variant="outline">
            <a href={shopHref}>
              {words.back}
              <IconArrowRight />
            </a>
          </Button>
        </div>
      ) : null}
    </div>
  );
}

/** A moment: a Date, an ISO 8601 string or epoch milliseconds. A date-only string such as "2026-10-05" is a calendar day. */
export type WarrantyMoment = Date | string | number;

/** The product that is being registered. */
export interface WarrantyProduct {
  /** What it is called: "Halcyon Aria air purifier". */
  name: string;
  /** The model or article number, as it is printed: "HX-200". It is written on a second line as "Model HX-200" and on the confirmation. */
  model?: string;
  /** A picture: a URL or a data URI. It is decorative, the name sits beside it. */
  image?: string;
}

/** What the customer filled in. It is what `onSubmit` receives. */
export interface WarrantyValues {
  /** The product's name: the one you passed, or what the customer typed when you passed none. */
  product: string;
  /** The serial number, trimmed and in capitals. */
  serial: string;
  /** The day it was bought, as yyyy-mm-dd. */
  purchaseDate: string;
  /** The shop's name, or the number of the order. */
  store: string;
  /** The receipt or invoice, or null when none was attached. */
  proof: File | null;
  /** True once the consent line was ticked: the form cannot be sent without it. */
  consent: boolean;
  /** The last day of the cover as yyyy-mm-dd: the purchase date plus `warrantyMonths`. */
  coveredUntil: string;
}

/** What `onSubmit` may hand back besides an error message: the reference of the registration, shown on the confirmation. */
export interface WarrantyReceipt {
  /** The registration's own number, as the shop's system knows it. */
  reference?: string;
}

const DAY = /^(\d{4})-(\d{2})-(\d{2})$/;
const two = (value: number): string => String(value).padStart(2, "0");

/** A zone name that would throw while rendering falls back to UTC. */
export function knownZone(timeZone: string): string {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone });
    return timeZone;
  } catch {
    return "UTC";
  }
}

/** The parts of a calendar day written yyyy-mm-dd, or null when it is not a real day (31 February). */
export function parseDay(iso: string): [year: number, month: number, day: number] | null {
  const found = DAY.exec(iso);
  if (!found) return null;
  const year = Number(found[1]);
  const month = Number(found[2]);
  const day = Number(found[3]);
  const probe = new Date(Date.UTC(year, month - 1, day));
  return probe.getUTCFullYear() === year && probe.getUTCMonth() === month - 1 && probe.getUTCDate() === day ? [year, month, day] : null;
}

/** A calendar day as yyyy-mm-dd. */
export function isoOfParts(year: number, month: number, day: number): string {
  return `${String(year).padStart(4, "0")}-${two(month)}-${two(day)}`;
}

/** The calendar day a Date shows on the reader's own wall clock, which is what a calendar picker hands back. */
export function isoOfDate(date: Date): string {
  return isoOfParts(date.getFullYear(), date.getMonth() + 1, date.getDate());
}

/** A calendar day as a Date at local midnight, which is what a calendar picker takes. Null for something that is not a day. */
export function dateOfIso(iso: string): Date | null {
  const parts = parseDay(iso);
  return parts ? new Date(parts[0], parts[1] - 1, parts[2]) : null;
}

/** The same day some months later, or the last day of that month when it is shorter (31 January plus a month is 28 February). */
export function addMonths(iso: string, months: number): string | null {
  const parts = parseDay(iso);
  if (!parts) return null;
  const [year, month, day] = parts;
  const index = year * 12 + (month - 1) + Math.trunc(months);
  const nextYear = Math.floor(index / 12);
  const nextMonth = (index % 12) + 1;
  const last = new Date(Date.UTC(nextYear, nextMonth, 0)).getUTCDate();
  return isoOfParts(nextYear, nextMonth, Math.min(day, last));
}

/**
 * The calendar day a moment falls on in a zone, as yyyy-mm-dd. A date-only string already is a calendar day.
 * Null when the moment is not a date.
 */
export function todayIn(moment: WarrantyMoment, timeZone: string): string | null {
  if (typeof moment === "string" && DAY.test(moment)) return moment;
  const instant = new Date(moment);
  if (Number.isNaN(instant.getTime())) return null;
  const parts = new Intl.DateTimeFormat("en-US", { timeZone: knownZone(timeZone), year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(instant);
  const pick = (type: string): string => parts.find((part) => part.type === type)?.value ?? "";
  return `${pick("year")}-${pick("month")}-${pick("day")}`;
}

/** A calendar day in words with its year: "14 March 2028". A day has no time zone, so it is written in UTC whatever the reader's zone. */
export function dayText(iso: string, locale: string): string {
  const parts = parseDay(iso);
  if (!parts) return iso;
  return new Intl.DateTimeFormat(locale, { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" }).format(new Date(Date.UTC(parts[0], parts[1] - 1, parts[2])));
}

/** A length of cover in the reader's words: whole years when it comes out even ("2 years"), months otherwise ("18 months"). */
export function durationText(months: number, locale: string): string {
  const whole = months >= 12 && months % 12 === 0;
  const value = whole ? months / 12 : months;
  try {
    return new Intl.NumberFormat(locale, { style: "unit", unit: whole ? "year" : "month", unitDisplay: "long" }).format(value);
  } catch {
    return `${value} ${whole ? "years" : "months"}`;
  }
}

/** A serial number as it is sent: trimmed, single spaces, capitals. */
export function tidySerial(value: string): string {
  return value.trim().replace(/\s+/g, " ").toUpperCase();
}

/**
 * A pattern as a RegExp that is safe to test repeatedly. A string is a regular expression's source and matches
 * without regard to case; a RegExp keeps its own flags, minus the ones that make `test` remember where it was.
 * Null when there is none, or when the string is not a valid expression.
 */
export function compilePattern(pattern: RegExp | string | undefined): RegExp | null {
  if (pattern === undefined) return null;
  try {
    return typeof pattern === "string" ? new RegExp(pattern, "i") : new RegExp(pattern.source, pattern.flags.replace(/[gy]/g, ""));
  } catch {
    return null;
  }
}

/** Whether a serial number fits the pattern. It is tried as typed and in capitals, since that is how it is sent. */
export function serialFits(pattern: RegExp | null, value: string): boolean {
  if (!pattern) return true;
  const typed = value.trim();
  return pattern.test(typed) || pattern.test(typed.toUpperCase());
}

/** The fields that can have an error, in the order they are on the page. */
export const FIELD_ORDER = ["product", "serial", "purchaseDate", "store", "proof", "consent"] as const;

export type FieldKey = (typeof FIELD_ORDER)[number];

export type FieldErrors = Partial<Record<FieldKey, string>>;

/** What a check needs to know besides the answers. */
export interface WarrantyRules {
  /** Whether the form asks for the product, because none was passed. */
  asksProduct: boolean;
  pattern: RegExp | null;
  /** The example of a serial number, for the message when the pattern is not met. Empty when there is none. */
  example: string;
  months: number;
  proofRequired: boolean;
  /** Today in the shop's zone as yyyy-mm-dd, or null when the clock is not known (then nothing is checked against it). */
  today: string | null;
  locale: string;
  errors: Required<WarrantyErrorWords>;
}

/** The answers as the form holds them. */
export interface WarrantyAnswers {
  product: string;
  serial: string;
  /** yyyy-mm-dd, or null when no day was chosen. */
  purchaseDate: string | null;
  store: string;
  proof: File | null;
  consent: boolean;
}

/** The words of each error, so every message stands alone. `{date}` and `{example}` are filled in by the check. */
export interface WarrantyErrorWords {
  product?: string;
  serial?: string;
  /** A serial number that does not fit the pattern. */
  serialMismatch?: string;
  /** Added to it when there is an example. `{example}`. */
  serialExample?: string;
  purchaseDate?: string;
  /** A day that has not happened yet. */
  purchaseDateFuture?: string;
  /** A day so long ago that the cover has ended. `{date}` is the last day of the cover. */
  purchaseDateEnded?: string;
  store?: string;
  proof?: string;
  consent?: string;
}

const fillIn = (template: string, values: Record<string, string>): string => template.replace(/\{(\w+)\}/g, (_, key: string) => values[key] ?? "");

/** The message for one field, or undefined when the field is fine. */
export function checkField(key: FieldKey, answers: WarrantyAnswers, rules: WarrantyRules): string | undefined {
  const { errors } = rules;
  switch (key) {
    case "product":
      return !rules.asksProduct || answers.product.trim() ? undefined : errors.product;
    case "serial": {
      if (!answers.serial.trim()) return errors.serial;
      if (serialFits(rules.pattern, answers.serial)) return undefined;
      return `${errors.serialMismatch}${rules.example ? ` ${fillIn(errors.serialExample, { example: rules.example })}` : ""}`;
    }
    case "purchaseDate": {
      const day = answers.purchaseDate;
      if (!day || !parseDay(day)) return errors.purchaseDate;
      if (rules.today && day > rules.today) return errors.purchaseDateFuture;
      const end = addMonths(day, rules.months);
      if (rules.today && end && end < rules.today) return fillIn(errors.purchaseDateEnded, { date: dayText(end, rules.locale) });
      return undefined;
    }
    case "store":
      return answers.store.trim() ? undefined : errors.store;
    case "proof":
      return !rules.proofRequired || answers.proof ? undefined : errors.proof;
    case "consent":
      return answers.consent ? undefined : errors.consent;
  }
}

/** Every problem in the form, by field. An empty object means it can be sent. */
export function validate(answers: WarrantyAnswers, rules: WarrantyRules): FieldErrors {
  const found: FieldErrors = {};
  for (const key of FIELD_ORDER) {
    const message = checkField(key, answers, rules);
    if (message) found[key] = message;
  }
  return found;
}

import type { WarrantyErrorWords } from "@rhs-ui/commerce/warranty-registration/warranty";

/** The name of each field. */
export interface WarrantyFieldWords {
  product?: string;
  /** The model line on the confirmation. */
  model?: string;
  serial?: string;
  purchaseDate?: string;
  store?: string;
  proof?: string;
}

/** The line under a field that needs one. */
export interface WarrantyHintWords {
  /** Under the product field, which is only there when you did not pass a product. */
  product?: string;
  /** Under the shop field. */
  store?: string;
  /** Under the receipt field. `{size}` is the largest file. */
  proof?: string;
}

/** Everything the form and its confirmation say. Pass the ones you want in another language or another voice. */
export interface WarrantyRegistrationLabels {
  /** The heading when the product is not known. */
  title?: string;
  /** The heading when it is. `{product}`. */
  titleNamed?: string;
  /** Under the heading. */
  description?: string;
  /** Under that, in small type. */
  requiredNote?: string;
  /** The name of every field. */
  fields?: WarrantyFieldWords;
  /** The line under a field that needs one. */
  hints?: WarrantyHintWords;
  /** The placeholder of the serial field when you gave no example. */
  serialPlaceholder?: string;
  /** The placeholder of the serial field when you gave an example, which is not a value and must not look like one. `{example}`. */
  serialPlaceholderExample?: string;
  /** The placeholder of the product field. */
  productPlaceholder?: string;
  /** The placeholder of the date picker. */
  datePlaceholder?: string;
  /** After the name of a field that may stay empty. */
  optional?: string;
  /** The button that attaches the receipt. */
  proofButton?: string;
  /** The consent line. */
  consent?: string;
  /** The link after it, when you passed `privacyHref`. */
  privacyLink?: string;
  /** The button, and while it works. */
  submit?: string;
  submitting?: string;
  /** Under the date, once a day is chosen: the end of the cover. `{date}`. */
  coveredUntil?: string;
  /** After it. `{duration}` is "2 years" or "18 months". */
  coveredFor?: string;
  /** The badge on the product: `{duration}` of warranty. */
  warrantyBadge?: string;
  /** The title and the three lines of what to have ready. */
  readyTitle?: string;
  ready?: readonly [string, string, string];
  /** The title of the notice when the registration could not be sent, and what it says when you gave no reason. */
  failedTitle?: string;
  failedMessage?: string;
  failedHint?: string;
  /** What a screen reader hears when the form is sent. `{date}`. */
  sentStatus?: string;
  /** The confirmation's heading when the product is not known. */
  sentTitle?: string;
  /** The heading when it is. `{product}`. */
  sentTitleNamed?: string;
  /** The small label above the end date. */
  sentCovered?: string;
  /** Under the date. `{duration}` and `{date}` is the day of purchase. */
  sentFrom?: string;
  /** The title of what the customer gave. */
  sentDetails?: string;
  /** The names of the details on the confirmation that are not form fields. */
  purchased?: string;
  /** Beside the shop or the order number on the confirmation. */
  boughtAt?: string;
  reference?: string;
  /** The line under the product's name when you passed a model. `{model}`. */
  modelLine?: string;
  /** The title of the lists of what is and is not covered. */
  coversTitle?: string;
  excludesTitle?: string;
  /** The link back to the shop. */
  back?: string;
  /** The error of each field. */
  errors?: WarrantyErrorWords;
}

export interface WarrantyWords extends Required<Omit<WarrantyRegistrationLabels, "fields" | "hints" | "errors">> {
  fields: Required<WarrantyFieldWords>;
  hints: Required<WarrantyHintWords>;
  errors: Required<WarrantyErrorWords>;
}

